type CitySize = "sm" | "md" | "lg";

const CITIES: {
  id: string;
  name: string;
  x: number;
  y: number;
  size: CitySize;
  labelDy?: number;
  labelAnchor?: "start" | "middle" | "end";
}[] = [
  { id: "delhi",      name: "Delhi",      x: 129.4, y: 101.7, size: "lg" },
  { id: "jaipur",     name: "Jaipur",     x: 111.4, y: 123.3, size: "md", labelDy: 14 },
  { id: "lucknow",    name: "Lucknow",    x: 177.1, y: 124.1, size: "md" },
  { id: "guwahati",   name: "Guwahati",   x: 314.4, y: 133.1, size: "sm" },
  { id: "kolkata",    name: "Kolkata",    x: 271.4, y: 178.6, size: "lg" },
  { id: "mumbai",     name: "Mumbai",     x: 74.3,  y: 223.0, size: "lg" },
  { id: "pune",       name: "Pune",       x: 86.8,  y: 230.1, size: "md", labelDy: 15 },
  { id: "hyderabad",  name: "Hyderabad",  x: 145.7, y: 244.7, size: "lg" },
  { id: "bengaluru",  name: "Bengaluru",  x: 134.3, y: 300.8, size: "lg" },
  { id: "chennai",    name: "Chennai",    x: 168.4, y: 299.4, size: "md", labelAnchor: "start", labelDy: -2 },
];

/* Hub — Bhopal, central India */
const HUB = { x: 132.0, y: 169.8 };

function dotR(s: CitySize) {
  return s === "lg" ? 4.5 : s === "md" ? 3.5 : 2.75;
}

export function IndiaMap3D() {
  const [active, setActive] = useState<string | null>(null);

  return (
    <div className="relative h-full w-full select-none overflow-hidden rounded-lg">
      <svg
        viewBox="0 0 400 377"
        fill="none"
        role="img"
        aria-label="CWP India chapters across the country"
        className="h-full w-full"
      >
        <defs>
          <filter id="im-soft" x="-60%" y="-60%" width="220%" height="220%">
            <feGaussianBlur stdDeviation="2.5" />
          </filter>
        </defs>

        {/* India landmass */}
        <path
          d={INDIA_PATH}
          fill="#e9f4ee"
          stroke="#a9cdb8"
          strokeWidth="1.2"
          strokeLinejoin="round"
        />

        {/* Connection lines */}
        {CITIES.map((c) => {
          const on = active === c.id;
          return (
            <g key={`l-${c.id}`}>
              <line
                x1={HUB.x} y1={HUB.y} x2={c.x} y2={c.y}
                stroke="#059669"
                strokeWidth={on ? "1" : "0.6"}
                strokeDasharray={on ? "none" : "3 4"}
                opacity={on ? 0.6 : 0.18}
                style={{ transition: "all 0.3s" }}
              />
              {on && (
                <circle r="2" fill="#059669" opacity="0.9">
                  <animateMotion dur="1.5s" repeatCount="indefinite" path={`M${HUB.x},${HUB.y} L${c.x},${c.y}`} />
                </circle>
              )}
            </g>
          );
        })}

        {/* City markers */}
        {CITIES.map((c) => {
          const r = dotR(c.size);
          const on = active === c.id;
          const labelY = c.labelDy !== undefined ? c.y + c.labelDy : c.y - r - 6;
          const labelX = c.labelAnchor === "start" ? c.x + r + 4 : c.x;
          return (
            <g
              key={c.id}
              onMouseEnter={() => setActive(c.id)}
              onMouseLeave={() => setActive(null)}
              style={{ cursor: "pointer" }}
            >
              <circle cx={c.x} cy={c.y} r={r + 6} fill="none" stroke="#10b981" strokeWidth="0.6">
                <animate attributeName="r" values={`${r + 3};${r + 10};${r + 3}`} dur="3.5s" repeatCount="indefinite" />
                <animate attributeName="opacity" values="0.45;0;0.45" dur="3.5s" repeatCount="indefinite" />
              </circle>
              {on && <circle cx={c.x} cy={c.y} r={r + 5} fill="#34d399" opacity="0.35" filter="url(#im-soft)" />}
              <circle cx={c.x} cy={c.y} r={r} fill={on ? "#047857" : "#059669"} stroke="#ffffff" strokeWidth="1" style={{ transition: "fill 0.3s" }} />
              <text
                x={labelX}
                y={labelY}
                textAnchor={c.labelAnchor ?? "middle"}
                fill={on ? "#064e3b" : "#52705f"}
                fontSize={c.size === "lg" ? "9" : "8"}
                fontFamily="var(--font-home-mono), ui-monospace, monospace"
                fontWeight={on ? "600" : "500"}
                letterSpacing="0.04em"
                style={{ transition: "fill 0.3s" }}
              >
                {c.name}
              </text>
            </g>
          );
        })}

        {/* Hub */}
        <circle cx={HUB.x} cy={HUB.y} r="11" fill="#ffffff" stroke="#059669" strokeWidth="1.4" />
        <text x={HUB.x} y={HUB.y + 2.5} textAnchor="middle" fill="#047857" fontSize="6.5" fontFamily="var(--font-home-mono), ui-monospace, monospace" fontWeight="700" letterSpacing="0.08em">
          CWP
        </text>
      </svg>
    </div>
  );
}
